class TestKeyGeneration:
    """Validate key generation, determinism, and entropy."""

    def test_keypair_generation(self, identity_manager):
        """Verify keypair generation produces valid keys."""
        result = identity_manager.generate_keypair()
        assert result is True
        assert identity_manager.has_keys()
        assert identity_manager.get_public_key() is not None

    def test_keypair_deterministic_with_seed(self):
        """Verify same seed produces same keypair."""
        manager1 = IdentityManager(seed=b"deterministic-seed-001")
        manager2 = IdentityManager(seed=b"deterministic-seed-001")
        
        manager1.generate_keypair()
        manager2.generate_keypair()
        
        assert manager1.get_public_key() == manager2.get_public_key()
        assert manager1.export_private_key() == manager2.export_private_key()

    def test_keypair_different_seeds(self):
        """Verify different seeds produce different keypairs."""
        manager1 = IdentityManager(seed=b"seed-001")
        manager2 = IdentityManager(seed=b"seed-002")
        
        manager1.generate_keypair()
        manager2.generate_keypair()
        
        assert manager1.get_public_key() != manager2.get_public_key()

    def test_key_entropy(self, identity_manager):
        """Verify generated keys have sufficient entropy."""
        identity_manager.generate_keypair()
        public_key = identity_manager.get_public_key()
        
        # Check key length (should be at least 256 bits for Ed25519)
        assert len(public_key) >= 32
        
        # Check entropy via Shannon entropy calculation
        entropy = self._calculate_entropy(public_key)
        assert entropy > 4.0, f"Low entropy detected: {entropy}"

    def test_key_export_import_roundtrip(self, identity_manager):
        """Verify key export/import roundtrip preserves identity."""
        identity_manager.generate_keypair()
        exported = identity_manager.export_private_key()
        
        new_manager = IdentityManager()
        new_manager.import_private_key(exported)
        
        assert new_manager.get_public_key() == identity_manager.get_public_key()

    def test_key_rotation(self, identity_manager):
        """Verify key rotation generates new keypair."""
        identity_manager.generate_keypair()
        original_key = identity_manager.get_public_key()
        
        identity_manager.rotate_keypair()
        new_key = identity_manager.get_public_key()
        
        assert original_key != new_key
        assert identity_manager.has_keys()

    @staticmethod
    def _calculate_entropy(data: bytes) -> float:
        """Calculate Shannon entropy of byte sequence."""
        if not data:
            return 0.0
        
        # Count byte frequencies
        freq = {}
        for byte in data:
            freq[byte] = freq.get(byte, 0) + 1
        
        # Calculate entropy
        import math
        length = len(data)
        entropy = 0.0
        for count in freq.values():
            p = count / length
            entropy -= p * math.log2(p)
        
        return entropy

