# Concurrency Safety
# ---------------------------------------------------------------------------
class TestConcurrency:
    """Validate thread safety and parallel operation integrity."""

    def test_parallel_signing(self, identity_manager_with_keys):
        """Verify parallel signing operations are safe."""
        payloads = [f"payload-{i}".encode() for i in range(50)]
        
        with ThreadPoolExecutor(max_workers=10) as executor:
            futures = [
                executor.submit(identity_manager_with_keys.sign, payload)
                for payload in payloads
            ]
            
            signatures = [f.result() for f in as_completed(futures)]
        
        # Verify all signatures
        for payload, signature in zip(payloads, signatures):
            assert identity_manager_with_keys.verify(payload, signature) is True

    def test_parallel_verify(self, identity_manager_with_keys, sample_payload):
        """Verify parallel verification operations are safe."""
        signature = identity_manager_with_keys.sign(sample_payload)
        
        with ThreadPoolExecutor(max_workers=10) as executor:
            futures = [
                executor.submit(
                    identity_manager_with_keys.verify, 
                    sample_payload, 
                    signature
                )
                for _ in range(100)
            ]
            
            results = [f.result() for f in as_completed(futures)]
        
        assert all(results)

    def test_parallel_key_generation(self):
        """Verify parallel key generation produces unique keys."""
        managers = [IdentityManager() for _ in range(10)]
        
        with ThreadPoolExecutor(max_workers=10) as executor:
            futures = [
                executor.submit(manager.generate_keypair)
                for manager in managers
            ]
            
            results = [f.result() for f in as_completed(futures)]
        
        assert all(results)
        
        # Verify all public keys are unique
        public_keys = [m.get_public_key() for m in managers]
        assert len(set(public_keys)) == len(public_keys)

    def test_concurrent_sign_verify_mixed(self, identity_manager_with_keys):
        """Verify mixed concurrent sign/verify operations."""
        payloads = [f"mixed-{i}".encode() for i in range(30)]
        
        def sign_and_verify(payload):
            signature = identity_manager_with_keys.sign(payload)
            return identity_manager_with_keys.verify(payload, signature)
        
        with ThreadPoolExecutor(max_workers=15) as executor:
            futures = [
                executor.submit(sign_and_verify, payload)
                for payload in payloads
            ]
            
            results = [f.result() for f in as_completed(futures)]
        
        assert all(results)

