        """Verify verification completes within 100ms."""
        signature = identity_manager_with_keys.sign(sample_payload)
        
        start_time = time.perf_counter()
        
        for _ in range(100):
            identity_manager_with_keys.verify(sample_payload, signature)
        
        elapsed = time.perf_counter() - start_time
        per_op = elapsed / 100
        
        assert per_op < 0.1, f"Verification too slow: {per_op:.4f}s per operation"

