class TestIntegration:
    """Validate integration scenarios and edge cases."""

    def test_full_identity_lifecycle(self, identity_manager):
        """Verify complete identity lifecycle."""
        # Generate keys
        identity_manager.generate_keypair()
        assert identity_manager.has_keys()
        
        # Sign and verify
        payload = b"lifecycle-test"
        signature = identity_manager.sign(payload)
        assert identity_manager.verify(payload, signature)
        
        # Export and import
        exported = identity_manager.export_private_key()
        new_manager = IdentityManager()
        new_manager.import_private_key(exported)
        
        # Verify with new manager
        assert new_manager.verify(payload, signature)
        
        # Rotate keys
        new_manager.rotate_keypair()
        assert new_manager.verify(payload, signature) is False

    def test_multiple_identities(self):
        """Verify multiple identities can coexist."""
        manager1 = IdentityManager(seed=b"identity-1")
        manager2 = IdentityManager(seed=b"identity-2")
        
        manager1.generate_keypair()
        manager2.generate_keypair()
        
        # Cross-verification should fail
        payload = b"cross-identity-test"
        sig1 = manager1.sign(payload)
        
        assert manager1.verify(payload, sig1) is True
        assert manager2.verify(payload, sig1) is False

    def test_serialization_roundtrip(self, identity_manager_with_keys, sample_payload):
        """Verify identity serialization roundtrip."""
        # Serialize identity
        serialized = identity_manager_with_keys.serialize()
        assert isinstance(serialized, dict)
        
        # Deserialize
        new_manager = IdentityManager.deserialize(serialized)
        
        # Verify operations work
        signature = new_manager.sign(sample_payload)
        assert new_manager.verify(sample_payload, signature)

    def test_hmac_operations(self, identity_manager_with_keys, sample_payload):
        """Verify HMAC operations."""
        hmac_value = identity_manager_with_keys.compute_hmac(sample_payload)
        
        # HMAC should be deterministic
        hmac_value2 = identity_manager_with_keys.compute_hmac(sample_payload)
        assert hmac_value == hmac_value2
        
        # Different payload should produce different HMAC
        different_hmac = identity_manager_with_keys.compute_hmac(b"different")
        assert hmac_value != different_hmac

    def test_metadata_integrity(self, identity_manager_with_keys, sample_metadata):
        """Verify metadata doesn't affect cryptographic operations."""
        identity_manager_with_keys.set_metadata(sample_metadata)
        
        payload = b"metadata-test"
        signature = identity_manager_with_keys.sign(payload)
        
        # Metadata shouldn't affect verification
        assert identity_manager_with_keys.verify(payload, signature)

    def test_empty_key_operations(self, identity_manager):
        """Verify operations with no keys raise appropriate errors."""
        with pytest.raises(KeyGenerationError):
            identity_manager.sign(b"test")
        
        with pytest.raises(KeyGenerationError):
            identity_manager.verify(b"test", b"signature")
        
        with pytest.raises(KeyGenerationError):
            identity_manager.compute_hmac(b"test")

